# Escaping only for ordinary plain text (mathematical LaTeX is intentional).
def plain(s):
    return s.replace('&',r'\&').replace('%',r'\%').replace('#',r'\#')
def emit(t):OUT.append(t)

def solution_steps(value):
    """Render authored numbered proof steps as a vertical list, preserving text."""
    hits=list(re.finditer(r'(?<!\S)([1-9])\.\s+',value))
    if len(hits)<2: return plain(value)
    steps=[]
    for ix,hit in enumerate(hits):
        stop=hits[ix+1].start() if ix+1<len(hits) else len(value)
        steps.append(value[hit.end():stop].strip())
    if not all(steps):return plain(value)
    return ('\\begin{enumerate}[label=\\arabic*),leftmargin=*,itemsep=3pt,topsep=4pt]\n'
        +'\n'.join('\\item '+plain(step) for step in steps)
        +'\n\\end{enumerate}\n')

